theorem summable_dirichletTerm {a : ι → ℂ} {mu : ι → ℝ} (hmu : ∀ i, 0 ≤ mu i) {v : ℝ}
    (hv : Summable (fun i => ‖a i‖ * Real.exp (-(mu i) * v))) {s : ℂ} (hs : v ≤ s.re) :
    Summable (fun i => a i * Complex.exp (-(mu i : ℂ) * s))

